"""Restore the instance's tests and test runner before a record is graded.

The policy works in the same checkout the grader then tests. Restoring the suite therefore
also means restoring conftest files and pytest configuration, and removing test files the
rollout added. Otherwise a patch can change collection or turn failed reports into passes.
"""
from __future__ import annotations

import subprocess
from pathlib import Path

TEST_FILE_PATTERNS = ("test_*.py", "*_test.py", "tests.py")
TEST_CONFIG_NAMES = (
    "conftest.py",
    "pytest.ini",
    "pyproject.toml",
    "setup.cfg",
    "tox.ini",
)


def _protected(path: Path, repo_root: Path) -> bool:
    if ".git" in path.parts or path.is_symlink():
        return False
    if path.name in TEST_CONFIG_NAMES:
        return True
    return any(path.match(pattern) for pattern in TEST_FILE_PATTERNS)


def iter_test_files(repo_root: Path):
    """Every test and pytest configuration file, relative to the repository root."""
    for path in sorted(repo_root.rglob("*")):
        if path.is_file() and _protected(path, repo_root):
            yield path.relative_to(repo_root)


def _git(repo_root: Path, *args: str) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["git", *args], cwd=str(repo_root),
        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
    )


def restore_tests(repo_root: Path) -> list[str]:
    """Restore tracked tests/configuration and delete untracked ones.

    A scratch checkout is disposable, so removal is confined to paths classified above and
    never follows symlinks. `git clean` handles ignored test files as well as ordinary ones.
    """
    tracked = _git(repo_root, "ls-files", "-z")
    paths = {
        rel for rel in tracked.stdout.split("\0")
        if rel and _protected(repo_root / rel, repo_root)
    }
    # Include untracked conftest/configuration and conventional test files.
    paths.update(str(rel) for rel in iter_test_files(repo_root))
    restored = sorted(paths)
    if restored:
        _git(repo_root, "checkout", "--", *restored)
        _git(repo_root, "clean", "-qfdx", "--", *restored)
    return restored

