from __future__ import annotations

import subprocess
from pathlib import Path

TEST_FILE_PATTERNS = ("test_*.py", "*_test.py", "tests.py")
TEST_CONFIG_NAMES = (
    "conftest.py",
    "pytest.ini",
    "pyproject.toml",
    "setup.cfg",
    "tox.ini",
)


def _protected(path: Path, repo_root: Path) -> bool:
    if ".git" in path.parts or path.is_symlink():
        return False
    if path.name in TEST_CONFIG_NAMES:
        return True
    return any(path.match(pattern) for pattern in TEST_FILE_PATTERNS)


